import { DatePipe } from '@angular/common';
import { Component, computed, inject, linkedSignal, resource, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import {
  CalendarRole,
  CalendarSummary,
  CalendarsService,
} from '../../../../core/calendars.service';
import { browserTimeZoneId, listTimeZoneIds } from '../../../../core/date-utils';
import { GroupSummary, GroupsService } from '../../../../core/groups.service';
import { TranslatePipe } from '../../../../core/i18n/translate.pipe';
import { createAction } from '../../../../shared/action-state/action-state';
import { IcalSubscribeLinks } from '../../../../shared/ical-subscribe-links/ical-subscribe-links';
import { Card } from '../../../../shared/card/card';
import { Icon } from '../../../../shared/icon/icon';

const ROLE_LABELS: Record<CalendarRole, string> = {
  Owner: 'admin.manageCalendars.roles.owner',
  Contributor: 'admin.manageCalendars.roles.contributor',
  Viewer: 'admin.manageCalendars.roles.viewer',
};

// Matches the backend's Calendar.DefaultIcon -- what a new calendar gets if this field is left as-is.
const DEFAULT_ICON = '📅';

// browserTimeZoneId() (Intl.DateTimeFormat().resolvedOptions().timeZone) can resolve to an alias
// like "UTC" that Intl.supportedValuesOf('timeZone') -- and so `timeZoneIds` -- does not include
// (it only lists canonical IANA names like "Etc/UTC"). Falling back to the first listed zone keeps
// the pre-selected value one the <select> actually has an <option> for, rather than silently
// submitting a value the guardian never saw selected.
function resolveDefaultTimeZoneId(candidates: readonly string[]): string {
  const browserZone = browserTimeZoneId();
  return candidates.includes(browserZone) ? browserZone : (candidates[0] ?? browserZone);
}

@Component({
  selector: 'app-manage-calendars',
  imports: [Icon, FormsModule, DatePipe, TranslatePipe, IcalSubscribeLinks, Card],
  templateUrl: './manage-calendars.html',
})
export class ManageCalendars {
  private readonly calendars = inject(CalendarsService);
  private readonly groupsService = inject(GroupsService);

  protected readonly roleLabels = ROLE_LABELS;
  protected readonly timeZoneIds = listTimeZoneIds();

  protected readonly items = resource({
    loader: () => this.calendars.listMyCalendars(),
  });

  // A calendar is always group-owned -- the create form stays hidden behind the needs-group hint
  // until a manageable group has loaded.
  private readonly groups = resource({ loader: () => this.loadManageableGroups() });
  protected readonly manageableGroups = computed<GroupSummary[]>(() => this.groups.value() ?? []);

  protected readonly newCalendarName = signal('');
  protected readonly newCalendarIcon = signal(DEFAULT_ICON);
  protected readonly newCalendarTimeZoneId = signal(resolveDefaultTimeZoneId(this.timeZoneIds));
  // Defaults to the first manageable group once they load.
  // Stryker disable next-line StringLiteral: with no manageable group the create form isn't rendered, and loading one recomputes this
  protected readonly newCalendarGroupId = linkedSignal(() => this.manageableGroups()[0]?.id ?? '');
  protected readonly creating = createAction();

  protected readonly movingCalendarId = signal<string | null>(null);
  // Stryker disable next-line StringLiteral: startMove() resets it to '' before the move form can render
  protected readonly moveTargetGroupId = signal('');
  protected readonly moving = createAction<string>();

  protected readonly editingIconCalendarId = signal<string | null>(null);
  // Stryker disable next-line StringLiteral: startEditIcon() sets it to the calendar's icon before the edit form can render
  protected readonly editIconValue = signal('');
  protected readonly updatingIcon = createAction<string>();

  protected readonly confirmingDeleteCalendarId = signal<string | null>(null);
  protected readonly deleting = createAction<string>();

  protected readonly icalCalendarId = signal<string | null>(null);
  // Loads the open panel's tokens; idle while no panel is open.
  protected readonly icalTokens = resource({
    params: () => this.icalCalendarId() ?? undefined,
    loader: ({ params }) => this.calendars.listIcalTokens(params),
  });
  protected readonly icalCreating = createAction();
  protected readonly icalRevoking = createAction<string>();
  // The plaintext URL is only ever available right after creation -- once this panel closes or a
  // new token is issued, it's gone from the client just like it's gone from the server.
  protected readonly newIcalUrl = signal<string | null>(null);
  // Stryker disable next-line BooleanLiteral: only read next to newIcalUrl, and createIcalToken() resets it to false before a URL can appear
  protected readonly icalCopied = signal(false);

  protected async createCalendar(): Promise<void> {
    const name = this.newCalendarName().trim();
    // Stryker disable next-line MethodExpression: the value only ever comes from listTimeZoneIds() <option>s, none of which carry whitespace
    const timeZoneId = this.newCalendarTimeZoneId().trim();
    const groupId = this.newCalendarGroupId();
    const icon = this.newCalendarIcon().trim() || null;

    if (!name || !timeZoneId || !groupId) {
      return;
    }

    await this.creating.run(
      true,
      async () => {
        await this.calendars.createCalendar({ name, timeZoneId, groupId, icon });
        this.newCalendarName.set('');
        this.newCalendarIcon.set(DEFAULT_ICON);
        this.items.reload();
      },
      'admin.manageCalendars.createError',
    );
  }

  protected startMove(calendarId: string): void {
    this.confirmingDeleteCalendarId.set(null);
    this.icalCalendarId.set(null);
    this.editingIconCalendarId.set(null);

    if (this.movingCalendarId() === calendarId) {
      this.movingCalendarId.set(null);
      return;
    }

    this.movingCalendarId.set(calendarId);
    this.moveTargetGroupId.set('');
    this.moving.clearError();
  }

  protected startEditIcon(calendar: CalendarSummary): void {
    this.movingCalendarId.set(null);
    this.confirmingDeleteCalendarId.set(null);
    this.icalCalendarId.set(null);

    if (this.editingIconCalendarId() === calendar.id) {
      this.editingIconCalendarId.set(null);
      return;
    }

    this.editingIconCalendarId.set(calendar.id);
    this.editIconValue.set(calendar.icon);
    this.updatingIcon.clearError();
  }

  protected async confirmEditIcon(calendarId: string): Promise<void> {
    const icon = this.editIconValue().trim();

    if (!icon) {
      return;
    }

    await this.updatingIcon.run(
      calendarId,
      async () => {
        await this.calendars.updateCalendarIcon(calendarId, icon);
        this.editingIconCalendarId.set(null);
        this.items.reload();
      },
      'admin.manageCalendars.editIcon.error',
    );
  }

  protected async confirmMove(calendarId: string): Promise<void> {
    const groupId = this.moveTargetGroupId();

    if (!groupId) {
      return;
    }

    await this.moving.run(
      calendarId,
      async () => {
        await this.calendars.transferToGroup(calendarId, groupId);
        this.movingCalendarId.set(null);
        this.items.reload();
      },
      'admin.manageCalendars.move.error',
    );
  }

  protected requestDelete(calendarId: string): void {
    this.movingCalendarId.set(null);
    this.icalCalendarId.set(null);
    this.editingIconCalendarId.set(null);
    this.deleting.clearError();
    this.confirmingDeleteCalendarId.set(calendarId);
  }

  protected cancelDelete(): void {
    this.confirmingDeleteCalendarId.set(null);
  }

  protected async confirmDelete(calendarId: string): Promise<void> {
    await this.deleting.run(
      calendarId,
      async () => {
        await this.calendars.deleteCalendar(calendarId);
        this.confirmingDeleteCalendarId.set(null);
        this.items.reload();
      },
      'admin.manageCalendars.delete.error',
    );
  }

  protected toggleIcal(calendarId: string): void {
    this.movingCalendarId.set(null);
    this.confirmingDeleteCalendarId.set(null);
    this.editingIconCalendarId.set(null);

    if (this.icalCalendarId() === calendarId) {
      this.icalCalendarId.set(null);
      return;
    }

    this.icalCalendarId.set(calendarId);
    this.newIcalUrl.set(null);
    this.icalCreating.clearError();
    this.icalRevoking.clearError();
  }

  protected async createIcalToken(calendarId: string): Promise<void> {
    this.newIcalUrl.set(null);
    this.icalCopied.set(false);

    await this.icalCreating.run(
      true,
      async () => {
        const issued = await this.calendars.createIcalToken(calendarId);
        this.newIcalUrl.set(this.calendars.icalFeedUrl(issued.subscriptionPath));
        // The reload replaces whatever the last revoke reported.
        this.icalRevoking.clearError();
        this.icalTokens.reload();
      },
      'admin.manageCalendars.ical.createError',
    );
  }

  protected async revokeIcalToken(calendarId: string, tokenId: string): Promise<void> {
    await this.icalRevoking.run(
      tokenId,
      async () => {
        await this.calendars.revokeIcalToken(calendarId, tokenId);
        this.icalTokens.reload();
      },
      'admin.manageCalendars.ical.revokeError',
    );
  }

  protected async copyIcalUrl(url: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(url);
      this.icalCopied.set(true);
    } catch {
      this.icalCopied.set(false);
    }
  }

  private async loadManageableGroups(): Promise<GroupSummary[]> {
    try {
      const groups = await this.groupsService.listMyGroups();
      // Group-owned calendar creation is gated on GroupAuthorization.CheckManage server-side,
      // which only Owners and Admins satisfy.
      return groups.filter((group) => group.role === 'Owner' || group.role === 'Admin');
    } catch {
      // No manageable groups, so the create form degrades to the needs-group hint.
      return [];
    }
  }
}

import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, resource, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';

import { listTimeZoneIds } from '../../../../core/date-utils';
import { FeaturesService } from '../../../../core/features.service';
import { TranslatePipe } from '../../../../core/i18n/translate.pipe';
import {
  LANGUAGE_NAMES,
  SUPPORTED_LANGUAGES,
  isSupportedLanguage,
} from '../../../../core/i18n/language';
import {
  ChildPasswordReset,
  ChildSummary,
  CreateChildResult,
  GuardianKind,
  GuardiansService,
} from '../../../../core/guardians.service';
import {
  BREAK_MINUTES_RANGE,
  FOCUS_MINUTES_RANGE,
  HomeworkChunks,
} from '../../../../core/homework-plan';
import { TransitionWarningsService } from '../../../../core/transition-warnings.service';
import { createAction } from '../../../../shared/action-state/action-state';
import { Card } from '../../../../shared/card/card';
import { Toggle } from '../../../../shared/toggle/toggle';

const INVITABLE_KINDS: GuardianKind[] = ['Parent', 'Guardian'];

const KIND_LABELS: Record<GuardianKind, string> = {
  Parent: 'admin.manageChildren.invite.kinds.parent',
  Guardian: 'admin.manageChildren.invite.kinds.guardian',
};

@Component({
  selector: 'app-manage-children',
  imports: [FormsModule, RouterLink, TranslatePipe, Card, Toggle],
  templateUrl: './manage-children.html',
})
export class ManageChildren {
  private readonly guardians = inject(GuardiansService);
  private readonly transitionWarnings = inject(TransitionWarningsService);
  protected readonly features = inject(FeaturesService);

  protected readonly invitableKinds = INVITABLE_KINDS;
  protected readonly kindLabels = KIND_LABELS;
  protected readonly languages = SUPPORTED_LANGUAGES;
  protected readonly languageNames = LANGUAGE_NAMES;
  protected readonly timeZoneIds = listTimeZoneIds();

  protected readonly children = resource({
    loader: () => this.guardians.listMyChildren(),
  });

  // Whether each child gets transition warnings ("Heads-up before changes: On/Off"), so a feature
  // that is off by default can be found. One request per child (a family has a handful); a child
  // whose request fails, or every child while the feature is off, gets no line.
  private readonly warningStatus = resource({
    params: () => (this.children.hasValue() ? this.children.value().map((c) => c.id) : undefined),
    loader: async ({ params }) => {
      if (!this.features.enabled('transitionWarnings')) {
        return {};
      }
      const entries = await Promise.all(
        params.map(async (childId) => {
          try {
            return [childId, (await this.transitionWarnings.getForChild(childId)).enabled] as const;
          } catch {
            return null;
          }
        }),
      );
      return Object.fromEntries(entries.filter((entry) => entry !== null)) as Record<
        string,
        boolean
      >;
    },
  });

  protected warningsOn(childId: string): boolean | undefined {
    return this.warningStatus.hasValue() ? this.warningStatus.value()[childId] : undefined;
  }

  protected readonly newChildGivenName = signal('');
  protected readonly newChildFamilyName = signal('');
  protected readonly newChildUsername = signal('');
  protected readonly addingChild = createAction();
  protected readonly lastCreatedChild = signal<CreateChildResult | null>(null);

  protected readonly confirmingRevokeChildId = signal<string | null>(null);
  protected readonly revokingChild = createAction<string>();

  // Deleting erases the child's account and data; only the sole guardian may (409 otherwise).
  protected readonly confirmingDeleteChildId = signal<string | null>(null);
  protected readonly deletingChild = createAction<string>();

  // A reset signs the child out, so it asks first; the new password is shown once, like a new child's.
  protected readonly confirmingResetChildId = signal<string | null>(null);
  protected readonly resettingPassword = createAction<string>();
  protected readonly lastPasswordReset = signal<
    (ChildPasswordReset & { givenName: string }) | null
  >(null);

  // One save at a time per setting, but each child keeps its own error until its next attempt.
  protected readonly savingLanguageChildId = signal<string | null>(null);
  protected readonly languageErrorByChildId = signal<Record<string, string>>({});

  protected readonly savingTimeZoneChildId = signal<string | null>(null);
  protected readonly timeZoneErrorByChildId = signal<Record<string, string>>({});

  protected readonly savingVisualTimersChildId = signal<string | null>(null);
  protected readonly visualTimersErrorByChildId = signal<Record<string, string>>({});

  protected readonly savingHomeworkChildId = signal<string | null>(null);
  protected readonly homeworkErrorByChildId = signal<Record<string, string>>({});
  protected readonly focusMinuteOptions = minuteOptions(FOCUS_MINUTES_RANGE, 5);
  protected readonly breakMinuteOptions = minuteOptions(BREAK_MINUTES_RANGE, 1);

  // Stryker disable next-line BooleanLiteral: the copy button only renders once lastCreatedChild is set, and addChild resets this to false at the same time
  protected readonly passwordCopied = signal(false);

  protected readonly expandedInviteChildId = signal<string | null>(null);
  // The expanded child's pending invites; idle while no invite panel is open.
  protected readonly invites = resource({
    params: () => this.expandedInviteChildId() ?? undefined,
    loader: ({ params: childId }) => this.guardians.listGuardianInvites(childId),
  });

  // Stryker disable next-line StringLiteral: the invite form only renders once toggleInvitePanel has reset this to ''
  protected readonly inviteEmail = signal('');
  protected readonly inviteKind = signal<GuardianKind>('Parent');
  protected readonly sendingInvite = createAction();
  protected readonly revokingInvite = createAction<string>();

  protected async addChild(): Promise<void> {
    const givenName = this.newChildGivenName().trim();
    const familyName = this.newChildFamilyName().trim();
    const username = this.newChildUsername().trim();

    if (!givenName || !familyName || !username) {
      return;
    }

    await this.addingChild.run(
      true,
      async () => {
        const created = await this.guardians.createChild({ givenName, familyName, username });
        this.lastCreatedChild.set(created);
        this.lastPasswordReset.set(null);
        this.passwordCopied.set(false);
        this.newChildGivenName.set('');
        this.newChildFamilyName.set('');
        this.newChildUsername.set('');
        this.children.reload();
      },
      (error) =>
        error instanceof HttpErrorResponse && error.status === 409
          ? 'admin.manageChildren.usernameTakenError'
          : 'admin.manageChildren.addError',
    );
  }

  protected requestRevoke(childId: string): void {
    this.revokingChild.clearError();
    this.confirmingDeleteChildId.set(null);
    this.confirmingResetChildId.set(null);
    this.confirmingRevokeChildId.set(childId);
  }

  protected cancelRevoke(): void {
    this.confirmingRevokeChildId.set(null);
  }

  protected async confirmRevoke(childId: string): Promise<void> {
    await this.revokingChild.run(
      childId,
      async () => {
        await this.guardians.revokeChild(childId);
        this.confirmingRevokeChildId.set(null);
        this.children.reload();
      },
      'admin.manageChildren.revokeError',
    );
  }

  protected requestDelete(childId: string): void {
    this.deletingChild.clearError();
    this.confirmingRevokeChildId.set(null);
    this.confirmingResetChildId.set(null);
    this.confirmingDeleteChildId.set(childId);
  }

  protected cancelDelete(): void {
    this.confirmingDeleteChildId.set(null);
  }

  protected async confirmDelete(childId: string): Promise<void> {
    await this.deletingChild.run(
      childId,
      async () => {
        await this.guardians.deleteChild(childId);
        this.confirmingDeleteChildId.set(null);
        this.children.reload();
      },
      (error) =>
        error instanceof HttpErrorResponse && error.status === 409
          ? 'admin.manageChildren.deleteOtherGuardiansError'
          : 'admin.manageChildren.deleteError',
    );
  }

  protected requestPasswordReset(childId: string): void {
    this.resettingPassword.clearError();
    this.confirmingRevokeChildId.set(null);
    this.confirmingDeleteChildId.set(null);
    this.confirmingResetChildId.set(childId);
  }

  protected cancelPasswordReset(): void {
    this.confirmingResetChildId.set(null);
  }

  protected async confirmPasswordReset(child: ChildSummary): Promise<void> {
    await this.resettingPassword.run(
      child.id,
      async () => {
        const reset = await this.guardians.resetChildPassword(child.id);
        this.lastPasswordReset.set({ ...reset, givenName: child.name.givenName });
        this.lastCreatedChild.set(null);
        this.passwordCopied.set(false);
        this.confirmingResetChildId.set(null);
      },
      'admin.manageChildren.resetPasswordError',
    );
  }

  protected languageErrorFor(childId: string): string | undefined {
    return this.languageErrorByChildId()[childId];
  }

  protected async changeLanguage(childId: string, language: string): Promise<void> {
    if (!isSupportedLanguage(language)) {
      return;
    }

    this.savingLanguageChildId.set(childId);
    this.languageErrorByChildId.update((byChildId) => withoutKey(byChildId, childId));

    try {
      const updated = await this.guardians.updateChildLanguage(childId, language);
      this.replaceChild(childId, updated);
    } catch {
      this.languageErrorByChildId.update((byChildId) => ({
        ...byChildId,
        [childId]: 'admin.manageChildren.language.error',
      }));
    } finally {
      this.savingLanguageChildId.set(null);
    }
  }

  protected timeZoneErrorFor(childId: string): string | undefined {
    return this.timeZoneErrorByChildId()[childId];
  }

  protected async changeTimeZone(childId: string, timeZoneId: string): Promise<void> {
    if (!timeZoneId) {
      return;
    }

    this.savingTimeZoneChildId.set(childId);
    this.timeZoneErrorByChildId.update((byChildId) => withoutKey(byChildId, childId));

    try {
      const updated = await this.guardians.updateChildTimeZone(childId, timeZoneId);
      this.replaceChild(childId, updated);
    } catch {
      this.timeZoneErrorByChildId.update((byChildId) => ({
        ...byChildId,
        [childId]: 'admin.manageChildren.timeZone.error',
      }));
    } finally {
      this.savingTimeZoneChildId.set(null);
    }
  }

  protected homeworkErrorFor(childId: string): string | undefined {
    return this.homeworkErrorByChildId()[childId];
  }

  protected async changeHomework(childId: string, chunks: HomeworkChunks): Promise<void> {
    this.savingHomeworkChildId.set(childId);
    this.homeworkErrorByChildId.update((byChildId) => withoutKey(byChildId, childId));

    // Show the pick straight away and put the saved lengths back if it fails: with a one-way
    // [ngModel], only a change of the bound value moves the select back, and the other select
    // builds its request from these lengths.
    const homeworkChunks = {
      focusMinutes: Number(chunks.focusMinutes),
      breakMinutes: Number(chunks.breakMinutes),
    };
    const previous = this.children.hasValue()
      ? this.children.value().find((child) => child.id === childId)
      : undefined;
    if (previous) {
      this.replaceChild(childId, { ...previous, homeworkChunks });
    }

    try {
      const updated = await this.guardians.updateChildHomeworkChunks(childId, homeworkChunks);
      this.replaceChild(childId, updated);
    } catch {
      if (previous) {
        this.replaceChild(childId, previous);
      }
      this.homeworkErrorByChildId.update((byChildId) => ({
        ...byChildId,
        [childId]: 'admin.manageChildren.homework.error',
      }));
    } finally {
      this.savingHomeworkChildId.set(null);
    }
  }

  protected visualTimersErrorFor(childId: string): string | undefined {
    return this.visualTimersErrorByChildId()[childId];
  }

  protected async changeVisualTimers(childId: string, showVisualTimers: boolean): Promise<void> {
    this.savingVisualTimersChildId.set(childId);
    this.visualTimersErrorByChildId.update((byChildId) => withoutKey(byChildId, childId));

    try {
      const updated = await this.guardians.updateChildVisualTimers(childId, showVisualTimers);
      this.replaceChild(childId, updated);
    } catch {
      this.visualTimersErrorByChildId.update((byChildId) => ({
        ...byChildId,
        [childId]: 'admin.manageChildren.visualTimers.error',
      }));
    } finally {
      this.savingVisualTimersChildId.set(null);
    }
  }

  protected toggleInvitePanel(childId: string): void {
    if (this.expandedInviteChildId() === childId) {
      this.expandedInviteChildId.set(null);
      return;
    }

    this.expandedInviteChildId.set(childId);
    this.inviteEmail.set('');
    this.inviteKind.set('Parent');
    this.sendingInvite.clearError();
    this.revokingInvite.clearError();
  }

  protected async sendGuardianInvite(childId: string): Promise<void> {
    const email = this.inviteEmail().trim();

    if (!email) {
      return;
    }

    await this.sendingInvite.run(
      true,
      async () => {
        await this.guardians.inviteGuardian(childId, { email, kind: this.inviteKind() });
        this.inviteEmail.set('');
        this.revokingInvite.clearError();
        this.invites.reload();
      },
      'admin.manageChildren.invite.sendError',
    );
  }

  protected async revokeGuardianInvite(childId: string, inviteId: string): Promise<void> {
    await this.revokingInvite.run(
      inviteId,
      async () => {
        await this.guardians.revokeGuardianInvite(childId, inviteId);
        this.invites.reload();
      },
      'admin.manageChildren.invite.cancelError',
    );
  }

  protected async copyPassword(password: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(password);
      this.passwordCopied.set(true);
    } catch {
      this.passwordCopied.set(false);
    }
  }

  private replaceChild(childId: string, updated: ChildSummary): void {
    // While a reload is in flight (or after it failed), updating would cancel it or throw; the
    // reload brings the fresh child anyway.
    if (!this.children.hasValue() || this.children.isLoading()) {
      return;
    }

    this.children.update((list) => list.map((child) => (child.id === childId ? updated : child)));
  }
}

function withoutKey(byChildId: Record<string, string>, childId: string): Record<string, string> {
  return Object.fromEntries(Object.entries(byChildId).filter(([id]) => id !== childId));
}

// Every whole-minute choice in `range`, `step` apart (5, 10, ... 45 for focus; 1 ... 15 for breaks).
function minuteOptions(range: { min: number; max: number }, step: number): number[] {
  return Array.from(
    { length: Math.floor((range.max - range.min) / step) + 1 },
    (_, i) => range.min + i * step,
  );
}

